const { Netmask } = require('netmask');
const { exec } = require('child_process');

const macLookup = require('./macLookup.js');

var flag;
const osType = os.type();

switch(osType) {
    case 'Windows_NT':
        flag = '-w';
        break;
    case 'Linux':
        flag = '-w';
        break;
    case 'Darwin':
        flag = '-t';
        break;
    default:
        throw new Error(`Unsupported OS: ${osType}`);
}

