  expect.assertions(2);
  const zip = require("bestzip");
  const fs = require("fs");
  const path = "./bestzip";
  try {
    if (fs.existsSync(path)) {
      fs.unlinkSync(path);
      console.log("File removed:", path);
    }
  } catch (err) {
    console.error(err);
  }
  file_exist = fs.existsSync(path);
