    var used = parts[2];
    var available = parts[3];
    if (!(isDigits(total) && isDigits(used) && isDigits(available))) {
        throw new Error('Unexpected df output: [' + dusage + ']');
    }

    return {
        total: total*1024,
        used: used*1024,
