   // regular expression engine. When processing a long sequence of spaces followed by 
   // a character that doesn't match the expected time unit, the engine greedily consumes 
   // the spaces, hits a mismatch, and begins exponential backtracking to try every 
   // possible boundary combination between overlapping whitespace matches.

   // A string of ~3500 spaces forces the backtracking depth far beyond safe thresholds.
   const maliciousPayload = Array(3500).join(" ") + "z";

