+  const visited = new Set();
+  /** @type {{ key: string, value: any }[][]} */
+  let toVisit = [
+    [{ key: null, value: start }]
+  ];
+
+  callback(toVisit[0]);
+
+  while (toVisit.length > 0) {
+    /** @type {{ key: string, value: any }[][]} */
+    const newToVisit = [];
