};

/*
  before
  function _Set() {}
  _Set.prototype.add = function(item) { ... };
  _Set.prototype.has = function(item) { ... };

  after
  var _Set = (function(){
    function _Set() {}
    _Set.prototype.add = function(item) { ... };
    _Set.prototype.has = function(item) { ... };
    return _Set;
  }())
