  console.log("🚨 [ReDoS Research PoC] Triggering catastrophic backtracking...");
  console.log(`   📥 Input length: ${maliciousUserPart.length} chars`);
  console.log(`   🔍 Payload suffix: ...${maliciousUserPart.slice(-10)} + 'x'\n`);

  const startTime = performance.now();

  try {
