    console.log(`📊 Backtrack estimate: > ${(2 ** 34).toLocaleString()} steps (exceeds 30,000 limit)`);

    if (elapsed > 1.5) { // Threshold varies by hardware; >1.5ms indicates heavy regex struggle
      console.error("✅ REPOSITORY VULNERABILITY CONFIRMED");
      console.error("   The engine spent exponential time trying all combination splits of the overlapping '.' matches.");
      console.error("   This input violates safe backtracking bounds and can block the event loop (~0.1s+ per request).");
